import type { Recipe } from '../types'

export function getDifficultyColor(difficulty: Recipe['difficulty']): string {
  switch (difficulty) {
    case 'Muy fácil': return 'bg-emerald-800/60 text-emerald-300 border border-emerald-700/50'
    case 'Fácil': return 'bg-green-800/60 text-green-300 border border-green-700/50'
    case 'Media': return 'bg-yellow-800/60 text-yellow-300 border border-yellow-700/50'
    case 'Media-Alta': return 'bg-orange-800/60 text-orange-300 border border-orange-700/50'
    case 'Difícil': return 'bg-red-800/60 text-red-300 border border-red-700/50'
    case 'Avanzado': return 'bg-purple-800/60 text-purple-300 border border-purple-700/50'
  }
}

